from rules import candidates, satisfies


def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best = None
    best_versions = None

    def ranges_for(name, constraints):
        ranges = list(constraints.get(name, ()))
        if name in roots:
            ranges.append(tuple(roots[name]))
        return ranges

    def allowed(name, version, constraints):
        if not satisfies(version, ranges_for(name, constraints)):
            return False
        if version in blocked.get(name, ()):
            return False
        if name in pins and version != pins[name]:
            return False
        return True

    def active_dependencies(row):
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(chosen):
        graph = {}
        for name, row in chosen.items():
            graph[name] = []
            for dep in active_dependencies(row):
                dep_name = dep['name']
                if dep_name not in chosen:
                    return False
                graph[name].append(dep_name)

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for neighbor in graph[name]:
                if not visit(neighbor):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(selected, assigned, constraints, chosen):
        nonlocal best, best_versions

        if best is not None:
            upper_bound = []
            for name in names:
                if name in assigned:
                    upper_bound.append(assigned[name])
                else:
                    available = [
                        row['version'] for row in packages[name]
                        if allowed(name, row['version'], constraints)
                    ]
                    upper_bound.append(max([-1] + available))
            if tuple(upper_bound) <= best:
                return

        unassigned = sorted(selected - assigned.keys())
        if not unassigned:
            if not is_acyclic(chosen):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best is None or vector > best:
                best = vector
                best_versions = dict(assigned)
            return

        name = unassigned[0]
        if name not in packages:
            return

        for row in candidates(packages[name]):
            version = row['version']
            if not allowed(name, version, constraints):
                continue

            next_selected = set(selected)
            next_selected.add(name)
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_chosen = dict(chosen)
            next_chosen[name] = row
            next_constraints = {
                key: list(value) for key, value in constraints.items()
            }

            valid = True
            for dep in active_dependencies(row):
                dep_name = dep['name']
                next_selected.add(dep_name)
                next_constraints.setdefault(dep_name, []).append(
                    (dep['min'], dep['max'])
                )
                if dep_name in next_assigned and not allowed(
                    dep_name, next_assigned[dep_name], next_constraints
                ):
                    valid = False
                    break
            if valid:
                search(next_selected, next_assigned, next_constraints, next_chosen)

    search(set(roots), {}, {}, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def candidates(rows):
    return sorted(rows, key=lambda row: row['version'], reverse=True)


def satisfies(version, ranges):
    return all(lower <= version <= upper for lower, upper in ranges)


def choose(rows):
    return max(row['version'] for row in rows)
